from dataclasses import dataclass

@dataclass
class StudyRecord:
    title: str
    minutes: int

def summary(record: StudyRecord) -> str:
    return f'{record.title}: {record.minutes} minutes'

print(summary(StudyRecord('Loops', 25)))
